-- =====================================================================
--  G-SMaRT Integrated Accounting and Government Contracting System
--  migration: letterheads, logos and signatories of the forms; the bid forms of steps 8 and 13;
--             the transaction types Cash Out and Kaliwaan (Barangay Contracts)
--
--  What it changes
--    1. Every proforma and form template can have a letterhead ({{letterhead}}: the company
--       letterhead or the barangay letterhead, both shared, or one of its own, with its logos and
--       pictures, lines of text, colours) and its signatories ({{signatories}}: names, positions,
--       words above, side by side), a footer at the bottom of the page, the colour of the table
--       headings and the way dates are written: all set on Proforma & Form Templates > Format.
--       The templates supplied with the program that were never changed get them in place of
--       their fixed company or barangay header and their fixed signatures (a new version; the one
--       before stays under Versions).
--    2. The papers of step 8 of the bidding (statement of ongoing contracts, statement of the single
--       largest completed similar contract, supplier profile, letter of intent, technical
--       specifications, production details / schedule of requirements, manpower requirements,
--       warranty) and of step 13 (notice of post-qualification, BAC resolution, notice of award,
--       notice to proceed) redesigned from the company's own forms: Legal paper, one-inch margins.
--       Three templates are new (supplier profile, technical specifications, notice of
--       post-qualification); the nine others get the new design as a new version (the version
--       before stays under Versions and can be put back).
--    3. The transaction types Cash Out (purchases) and Kaliwaan (purchases) in Contracting
--       Settings, with their boxes on the transaction form and their marks on the pre-printed pad.
--       Each step and paper of the SOP can be limited to some types of transaction (SOP Steps &
--       Papers): a transaction of another type skips it.
--    4. Two columns (brgy_sop_steps.txn_types, brgy_sop_papers.txn_types), settings for the
--       representative's title and cellphone, the person managing the firm and the liaison
--       officer, one kind of document and one paper (notice of post-qualification).
--       Nothing is deleted and no amount changes.
--
--  For an EXISTING database that already has the migration 2026_11_03_barangay_sop_forms.sql.
--  New installs do not need it (schema.sql and tools/install.php include everything).
--  With several companies, run it on every company database (Super Admin: Companies >
--  Database updates > Update all companies).
--  Safe to run more than once. Written for MySQL 5.5 (no ADD COLUMN IF NOT EXISTS, no JSON
--  functions: every column is added through a check of information_schema).
--
--  How to run (back up the database first):
--    phpMyAdmin: click the database > Import > choose this file > Go
--    Navicat:    right-click the database > Execute SQL File
--    or:         mysql -u root -p government_contracting_system < 2026_11_10_letterheads_bid_forms_types.sql
-- =====================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------
--  1. New columns (each added only when it is not there yet)
-- ---------------------------------------------------------------------
SET @sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE brgy_sop_steps ADD COLUMN txn_types VARCHAR(255) NULL AFTER role_hint', 'DO 0') FROM information_schema.columns
             WHERE table_schema = DATABASE() AND table_name = 'brgy_sop_steps' AND column_name = 'txn_types');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
SET @sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE brgy_sop_papers ADD COLUMN txn_types VARCHAR(255) NULL AFTER description', 'DO 0') FROM information_schema.columns
             WHERE table_schema = DATABASE() AND table_name = 'brgy_sop_papers' AND column_name = 'txn_types');
PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;

-- ---------------------------------------------------------------------
--  2. Settings: the new types of transaction and the people on the forms
-- ---------------------------------------------------------------------
INSERT IGNORE INTO settings (setting_key, setting_value) VALUES ('brgy_signatory_title', 'Mr.'),
  ('brgy_signatory_mobile', ''),
  ('brgy_manager_name', ''),
  ('brgy_manager_position', ''),
  ('brgy_manager_phone', ''),
  ('brgy_manager_mobile', ''),
  ('brgy_liaison_name', ''),
  ('brgy_liaison_position', 'Liaison Officer'),
  ('brgy_liaison_phone', ''),
  ('brgy_liaison_mobile', ''),
  ('brgy_txn_types', 'cash_out|Cash Out (purchases)\nkaliwaan|Kaliwaan (purchases)\npurchases|Purchases\nconstruction|Construction');
-- Cash Out and Kaliwaan before the types already there (a list changed by the company keeps its own types)
UPDATE settings SET setting_value = CONCAT('kaliwaan|Kaliwaan (purchases)\n', setting_value) WHERE setting_key = 'brgy_txn_types' AND CONCAT('\n', setting_value) NOT LIKE '%\nkaliwaan|%';
UPDATE settings SET setting_value = CONCAT('cash_out|Cash Out (purchases)\n', setting_value) WHERE setting_key = 'brgy_txn_types' AND CONCAT('\n', setting_value) NOT LIKE '%\ncash\_out|%';

-- ---------------------------------------------------------------------
--  3. The notice of post-qualification: its kind of document and its paper, in step 13
-- ---------------------------------------------------------------------
SET @o = (SELECT COALESCE(MAX(sort_order), 0) FROM brgy_doc_types);
INSERT IGNORE INTO brgy_doc_types (code, name, doc_group, is_company, needs_validity, validity_months, sort_order, is_active) VALUES ('post_qual_notice', 'Notice of post-qualification', 'contract', 0, 0, NULL, @o + 10, 1);
SET @o = (SELECT COALESCE(MAX(sort_order), 0) FROM brgy_sop_papers);
-- Supplier profile: prepared with its new template
UPDATE brgy_sop_papers SET template_code = 'supplier_profile', description = 'The supplier profile asked by the barangay: the firm, the person managing its affairs, the liaison officer.' WHERE code = 'supplier_profile' AND template_code = 'company_profile';
UPDATE brgy_project_papers SET template_code = 'supplier_profile' WHERE paper_code = 'supplier_profile' AND template_code = 'company_profile' AND form_id IS NULL AND document_id IS NULL;
-- Technical specifications: prepared with its new template
UPDATE brgy_sop_papers SET template_code = 'technical_specifications', description = 'Section VII: the specifications with the statement of compliance.' WHERE code = 'tech_specs' AND template_code = 'technical_proposal';
UPDATE brgy_project_papers SET template_code = 'technical_specifications' WHERE paper_code = 'tech_specs' AND template_code = 'technical_proposal' AND form_id IS NULL AND document_id IS NULL;
INSERT IGNORE INTO brgy_sop_papers (code, name, doc_type, template_code, source, copies, needs_signature, needs_notary, needs_ctc, condition_code, description, sort_order, is_active) VALUES ('post_qual_notice', 'Notice of post-qualification', 'post_qual_notice', 'notice_of_post_qualification', 'prepare', 1, 1, 0, 0, NULL, 'The BAC informs the company that it passed the post-qualification; received by the company.', @o + 10, 1);
UPDATE brgy_sop_steps SET papers = 'post_qual_notice,bac_resolution,noa,ntp,post_qual', instructions = 'For the winner: Notice of Post Qualification, BAC Resolution, Notice of Award (NOA), Notice to Proceed (NTP), Post-Qualification Documents.' WHERE code = 'bid13' AND papers = 'bac_resolution,noa,ntp,post_qual';

-- ---------------------------------------------------------------------
--  4. The three new templates (supplier profile, technical specifications, notice of post-qualification)
-- ---------------------------------------------------------------------
SET @o = (SELECT COALESCE(MAX(sort_order), 0) FROM brgy_templates);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('supplier_profile', 'Supplier profile', 'proforma', 'bid', 'company_profile', 'The supplier profile asked by the barangay (step 8 of the bidding): the firm, its general information, the person managing its affairs and the authorized liaison officer (Contracting Settings).', '<div>{{letterhead}}</div><p style=\"text-align:center;margin:14px 0 28px\"><span style=\"font-size:20pt;font-weight:bold;text-decoration:underline\">SUPPLIER</span></p><p style=\"margin:0 0 6px\"><b><u>Profile</u></b></p><table class=\"fx-plain fx-kv\" style=\"width:100%\"><tbody><tr><td class=\"k\" style=\"width:34%\">Date</td><td>: {{date.today}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Name of Firm/Company</td><td>: <b>{{company.name_upper}}</b></td></tr><tr><td class=\"k\" style=\"width:34%\">Tax Account Number</td><td>: {{company.tin}}</td></tr></tbody></table><p style=\"margin:18px 0 6px\"><b><u>General Information</u></b></p><table class=\"fx-plain fx-kv\" style=\"width:100%\"><tbody><tr><td class=\"k\" style=\"width:34%\">Address</td><td>: {{company.address}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Telephone Number</td><td>: {{company.phone}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Email Address</td><td>: {{company.email}}</td></tr></tbody></table><p style=\"margin:18px 0 6px\"><b><u>Legal Aspect</u></b></p><p style=\"margin:0 0 6px\">Persons Managing affairs of the Firm</p><table class=\"fx-plain fx-kv\" style=\"width:100%\"><tbody><tr><td class=\"k\" style=\"width:34%\">Name</td><td>: {{company.manager_upper}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Designation</td><td>: {{company.manager_position}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Telephone</td><td>: {{company.manager_phone}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Cellphone No.</td><td>: {{company.manager_mobile}}</td></tr></tbody></table><p style=\"margin:18px 0 6px\">Authorized Liaison Officer</p><table class=\"fx-plain fx-kv\" style=\"width:100%\"><tbody><tr><td class=\"k\" style=\"width:34%\">Name</td><td>: {{company.liaison_upper}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Designation</td><td>: {{company.liaison_position}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Telephone</td><td>: {{company.liaison_phone}}</td></tr><tr><td class=\"k\" style=\"width:34%\">Cellphone No.</td><td>: {{company.liaison_mobile}}</td></tr></tbody></table>', 'Legal', 'portrait', 0, 'company.name,company.tin', 0, 'layout', '{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"signatories\":[],\"lh_style\":\"own\",\"lh_left\":\"none\",\"lh_right\":\"none\",\"lh_lines\":\"Republic of the Philippines\\nProvince of {{entity.province}}\\n{{entity.lgu_line}}\\n**{{entity.short_upper}} Barangay Hall**\",\"lh_align\":\"center\",\"lh_font\":\"\",\"lh_size\":11,\"lh_big\":16,\"lh_pic_mm\":24,\"lh_box\":0,\"lh_box_bg\":\"#ffffff\",\"lh_box_fg\":\"#111111\",\"lh_rule\":0,\"lh_rule_color\":\"#111111\",\"lh_space\":8,\"lh_pic_a\":\"\",\"lh_pic_b\":\"\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}', NULL, 1, 1, @o + 10);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('technical_specifications', 'Technical specifications (Section VII) with the statement of compliance', 'proforma', 'bid', 'technical_proposal', 'Section VII - Technical specifications of the bid (step 8 of the bidding): each item with its specifications, one a line, and the statement of compliance. A line in capitals or ending with \":\" prints bold; **text** is bold too.', '<p style=\"text-align:center;margin:0 0 20px\"><span style=\"font-size:16pt;font-weight:bold;text-decoration:underline\">SECTION VII-TECHNICAL SPECIFICATIONS</span></p><p><b>Date:</b> {{date.today}}</p><p>To: {{entity.short}} Barangay Hall, {{entity.city}}, {{entity.province}}<br>Address: {{entity.address}}</p><p>Gentlemen and/ or Ladies,</p><div>{{specs.items}}</div><p style=\"margin-top:10px\">We can <b><u>comply</u></b> the technical specification stated in the Bid Form.</p><div>{{signatories}}</div>', 'Legal', 'portrait', 0, 'entity.name,project.title', 0, 'layout', '{\"margin_top\":22,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"lh_style\":\"none\",\"sig_cols\":1,\"sig_top\":16,\"sig_space\":14,\"comply_text\":\"\\\"comply\\\"\",\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"Dealer\'s Signature\",\"extra\":\"**{{company.name_upper}}**\\n{{company.address}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}', NULL, 1, 1, @o + 20);
INSERT IGNORE INTO brgy_templates (code, name, category, stage, doc_type, description, body, paper, orientation, is_prescribed, required_fields, needs_approval, print_mode, layout_json, positions_json, version_no, is_active, sort_order) VALUES ('notice_of_post_qualification', 'Notice of post-qualification', 'proforma', 'award', 'post_qual_notice', 'Notice of the BAC that the company passed the post-qualification and its bid is the lowest calculated and responsive bid (step 13 of the bidding), prepared for the BAC Chairman\'s signature.', '<div>{{letterhead}}</div><p style=\"text-align:center;margin:4px 0 22px\"><span style=\"font-size:14pt;font-weight:bold\">Notice of Post Qualification</span></p><p>{{date.today}}</p><p style=\"margin-top:18px\"><b>{{signatory.addressee}}</b><br>{{signatory.position_upper}}<br><b>{{company.name_upper}}</b><br>{{company.address}}</p><p style=\"margin-top:22px\"><b><u>ATTN.: {{signatory.addressee}}</u></b></p><p style=\"margin-top:22px\">Good day!</p><p style=\"text-align:justify;line-height:1.7\">After determining your bid as the Lowest Calculated Bid for the <b>{{project.title}}</b> for {{entity.title}}, {{entity.city}} and upon the post qualification involving the careful examination, validation and verification of the eligibility, technical and financial requirements that you have submitted for bidding. We are happy to inform you that you have successfully passed the Post Qualification and therefore, now consider your bid as the Lowest Calculated and Responsive for the said Contract.</p><div>{{signatories}}</div>', 'Legal', 'portrait', 0, 'entity.name,project.title', 0, 'layout', '{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":14,\"sig_space\":10,\"sig_gap\":8,\"signatories\":[{\"lead\":\"Very truly yours,\",\"name\":\"HON. {{entity.bac_chair_upper}}\",\"pos\":\"BAC CHAIRMAN\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":1},{\"lead\":\"Received by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"PRINTED NAME AND SIGNATURE\",\"extra\":\"\",\"align\":\"left\",\"newrow\":1,\"line\":0,\"bold\":0,\"underline\":1,\"upper\":0,\"italic\":1}],\"footer\":\"OFFICE OF THE BARANGAY\",\"footer_align\":\"center\",\"footer_bold\":1,\"footer_size\":11,\"footer_pos\":\"bottom\",\"lh_style\":\"barangay\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"Cambria\"}', NULL, 1, 1, @o + 30);

-- ---------------------------------------------------------------------
--  5. The nine papers of steps 8 and 13 redesigned from the company's forms: a new version of each
--     (only once: a template that already has {{signatories}} or a statement table is left as it is)
-- ---------------------------------------------------------------------
UPDATE brgy_templates SET name = 'Statement of all ongoing government and private contracts', description = 'Ongoing government and private contracts, incl. those awarded but not started (step 8 of the bidding): the company\'s other awarded contracts not closed fill the government part; private ones are typed on the form.', body = '<p style=\"margin:0;line-height:1.3\"><i>Procuring Entity:</i> <b>{{entity.title}}</b><br><i>Name of the Project:</i> <b>{{project.title}}</b><br><i>Location of the Project:</i> <b>{{project.location}}</b></p><p style=\"margin:8px 0 6px\"><span class=\"fx-hl\" style=\"font-size:14pt;font-weight:bold\">Statement of all Ongoing Government &amp; Private Contracts including contracts awarded but not yet started</span></p><table class=\"fx-plain fx-kv\" style=\"margin:4px 0 6px\"><tbody><tr><td class=\"k\">Business Name</td><td>: <u>{{company.name}}</u></td></tr><tr><td class=\"k\">Business Address</td><td>: <u>{{company.address}}</u></td></tr></tbody></table><div style=\"margin-top:6px\">{{contracts.ongoing_table}}</div><p style=\"margin:6px 0 0\">Note: This statement shall be supported with:</p><ol style=\"margin:0;padding-left:2.4em\"><li>Purchase Order / Notice to Proceed</li><li>Notice of Award</li></ol><table class=\"fx-plain fx-kv\" style=\"margin-top:22px\"><tbody><tr><td class=\"k\" style=\"width:110px\">Submitted by</td><td>: <b><u>{{signatory.name}}</u></b></td></tr><tr><td></td><td style=\"padding-left:14px;font-size:.92em\">(Printed Name &amp; Signature)</td></tr><tr><td class=\"k\">Designation</td><td>: <u>{{signatory.position}}</u></td></tr><tr><td class=\"k\">Date</td><td>: {{date.today}}</td></tr></tbody></table>', paper = 'Legal', orientation = 'landscape', layout_json = '{\"margin_top\":15,\"margin_right\":18,\"margin_bottom\":15,\"margin_left\":18,\"line_height\":1.25,\"cell_pad\":3,\"font_size\":10,\"table_size\":9.5,\"title_size\":14,\"paper\":\"Legal\",\"orientation\":\"landscape\",\"font\":\"CG Omega\",\"date_style\":\"mdy\",\"lh_style\":\"none\",\"signatories\":[]}', required_fields = 'company.name,project.title', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'statement_ongoing_contracts' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';
UPDATE brgy_templates SET name = 'Statement of the single largest completed contract similar to the contract to be bid (SLCC)', description = 'Statement identifying the bidder\'s single largest completed contract similar to the contract to be bid (step 8 of the bidding): the largest closed contract of the company of the same category.', body = '<p style=\"margin:0;line-height:1.3\"><i>Procuring Entity:</i> <b>{{entity.title}}</b><br><i>Name of the Project:</i> <b>{{project.title}}</b><br><i>Location of the Project:</i> <b>{{project.location}}</b></p><p style=\"margin:6px 0 6px\"><span class=\"fx-hl\" style=\"font-size:14pt;font-weight:bold\">Statement identifying the bidder’s single largest completed contract similar to the contract to be bid</span></p><table class=\"fx-plain fx-kv\" style=\"margin:4px 0 6px\"><tbody><tr><td class=\"k\">Business Name</td><td>: <u>{{company.name}}</u></td></tr><tr><td class=\"k\">Business Address</td><td>: <u>{{company.address}}</u></td></tr></tbody></table><div style=\"margin-top:6px\">{{contracts.slcc_table}}</div><p style=\"margin:6px 0 0\">Note: This statement shall be supported with:</p><p style=\"margin:0;padding-left:2em\">1. Purchase Order     2. Sales Invoice     3. Certificate of Completion / Delivery Receipt     4. Notice of Award     5. Notice to Proceed</p><table class=\"fx-plain fx-kv\" style=\"margin-top:22px\"><tbody><tr><td class=\"k\" style=\"width:110px\">Submitted by</td><td>: <b><u>{{signatory.name}}</u></b></td></tr><tr><td></td><td style=\"padding-left:14px;font-size:.92em\">(Printed Name &amp; Signature)</td></tr><tr><td class=\"k\">Designation</td><td>: <u>{{signatory.position}}</u></td></tr><tr><td class=\"k\">Date</td><td>: {{date.today}}</td></tr></tbody></table>', paper = 'Folio', orientation = 'landscape', layout_json = '{\"margin_top\":15,\"margin_right\":18,\"margin_bottom\":15,\"margin_left\":18,\"line_height\":1.25,\"cell_pad\":3,\"font_size\":10,\"table_size\":9.5,\"title_size\":14,\"paper\":\"Folio\",\"orientation\":\"landscape\",\"font\":\"CG Omega\",\"date_style\":\"mdy\",\"lh_style\":\"none\",\"signatories\":[]}', required_fields = 'company.name,project.title', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'statement_similar_contracts' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';
UPDATE brgy_templates SET name = 'Letter of intent (manifestation of intent to participate)', description = 'Manifestation of intent to participate in the public bidding (step 8 of the bidding), on the company letterhead.', body = '<div>{{letterhead}}</div><p style=\"text-align:center;margin:22px 0 26px\"><span style=\"font-size:16pt;font-weight:bold\">Manifestation of Intent to Participate</span></p><p><b>{{date.today}}</b></p><p style=\"margin-top:18px\"><b>OFFICE OF THE CHAIRMAN</b><br>Bids and Awards Committee<br><b>{{entity.title}}</b><br>{{entity.city}}, {{entity.province}}</p><p>Dear Sir/Madam:</p><p style=\"text-align:justify\">This refers to the procurement project entitled <b>{{project.title}}.</b></p><p style=\"text-align:justify\">In this regard, <b>{{company.name}}</b>, with business address at <b>{{company.address}}</b>, hereby formally manifests its intent to participate in the public bidding for the above-mentioned project, in accordance with {{project.law_text}} and its Implementing Rules and Regulations (IRR).</p><p style=\"text-align:justify\">This manifestation is submitted in compliance with the requirements of the Bidding Documents issued by your office. Should our participation be accepted, we commit to comply with all eligibility requirements, submission of bidding documents, and other conditions set forth by the Bids and Awards Committee (BAC) within the prescribed timelines.</p><p style=\"text-align:justify\">We trust that this manifestation satisfies your requirement for expression of interest. We look forward to participating in the bidding process.</p><p style=\"margin-top:18px\">Thank you for your consideration.</p><div>{{signatories}}</div>', paper = 'Legal', orientation = 'portrait', layout_json = '{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":12,\"sig_space\":12,\"lh_space\":4,\"signatories\":[{\"lead\":\"Respectfully yours,\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}', required_fields = 'entity.name,project.title', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'letter_of_intent' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';
UPDATE brgy_templates SET name = 'Production details (Section VI: schedule of requirements)', description = 'Section VI - Schedule of requirements (step 8 of the bidding): the items with their specifications, the quantity, and the delivery period in weeks or months.', body = '<div>{{letterhead}}</div><p style=\"text-align:center;margin:8px 0 18px\"><span style=\"font-size:16pt;font-weight:bold;text-decoration:underline\">SECTION VI-SCHEDULE OF REQUIREMENTS</span></p><div>{{sched.items}}</div><div>{{signatories}}</div>', paper = 'Legal', orientation = 'portrait', layout_json = '{\"margin_top\":20,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":1,\"font_size\":10,\"table_size\":9.5,\"title_size\":14,\"sig_cols\":1,\"sig_top\":14,\"sig_space\":14,\"th_bg\":\"#fff2cc\",\"signatories\":[{\"lead\":\"**{{company.name_upper}}**\\n{{company.address_upper}}\",\"name\":\"{{signatory.name}}\",\"pos\":\"Dealer\'s Signature\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"own\",\"lh_left\":\"none\",\"lh_right\":\"none\",\"lh_lines\":\"Republic of the Philippines\\nProvince of {{entity.province}}\\n{{entity.lgu_line}}\\n**{{entity.short}}** Barangay Hall\",\"lh_align\":\"center\",\"lh_font\":\"\",\"lh_size\":11,\"lh_big\":16,\"lh_pic_mm\":24,\"lh_box\":0,\"lh_box_bg\":\"#ffffff\",\"lh_box_fg\":\"#111111\",\"lh_rule\":0,\"lh_rule_color\":\"#111111\",\"lh_space\":8,\"lh_pic_a\":\"\",\"lh_pic_b\":\"\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}', required_fields = 'entity.name,project.title', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'production_details' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';
UPDATE brgy_templates SET name = 'Manpower schedule (manpower requirements)', description = 'Manpower requirements of the delivery (step 8 of the bidding), on the company letterhead.', body = '<div>{{letterhead}}</div><p style=\"text-align:center;margin:18px 0 30px\"><span style=\"font-size:18pt;font-weight:bold\">MANPOWER REQUIREMENTS</span></p><p style=\"text-align:justify\">In compliance with the requirements of the Bids and Awards Committee (BAC), and based on our standard delivery procedures and actual delivery operations, the following manpower requirement is hereby submitted:</p><p style=\"text-align:justify\">All goods and services shall be delivered to the designated delivery site and shall be subject to inspection upon delivery.</p><table class=\"fx\" style=\"width:100%;margin-top:22px\"><thead><tr><th style=\"width:28%\">PARTICULARS</th><th>DETAILS</th></tr></thead><tbody><tr><td><b>Project Name:</b></td><td>{{project.title}}</td></tr><tr><td style=\"vertical-align:middle\"><b>Project Location:</b></td><td>{{project.location}}</td></tr><tr><td><b>Delivery Vehicle:</b></td><td>Any available vehicle</td></tr><tr><td style=\"vertical-align:middle\"><b>Required Personnel</b></td><td>At least two (2) personnel composed of:<br>• One (1) Driver<br>• One (1) Sales Representative</td></tr></tbody></table><div>{{signatories}}</div>', paper = 'Legal', orientation = 'portrait', layout_json = '{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":22,\"sig_space\":12,\"signatories\":[{\"lead\":\"Respectfully submitted by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}', required_fields = 'project.title', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'manpower_schedule' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';
UPDATE brgy_templates SET name = 'Warranty certificate (after-sales service and warranty provision)', description = 'After-sales service and warranty provision (step 8 of the bidding), on the company letterhead. The warranty period comes from the project (warranty in months).', body = '<div>{{letterhead}}</div><p style=\"text-align:center;margin:10px 0 14px\"><span style=\"font-size:11.5pt;font-weight:bold\">After-Sales Service and Warranty Provision</span></p><p style=\"text-align:justify\">The Supplier shall warrant that the {{project.title}}, including all its components, accessories, and attachments, is brand new, free from defects in materials and workmanship, and compliant with the technical specifications prescribed in the Contract.</p><p style=\"margin-bottom:0\"><b>1. Warranty Period</b></p><p style=\"text-align:justify\">The warranty shall be for a minimum period of <b>{{project.warranty_words}}</b>, reckoned from the date of final acceptance by the Procuring Entity.</p><p style=\"margin-bottom:0\"><b>2. Scope of Warranty</b></p><p style=\"margin-bottom:2px\">The warranty shall cover, but not be limited to, defects or failures in the following:</p><ul style=\"margin-top:4px\"><li>Materials and workmanship of every item delivered</li><li>The performance of the goods according to the technical specifications</li><li>Components, parts, and assemblies</li><li>Electrical, mechanical, and operating systems, where applicable</li><li>All factory-installed parts, equipment, and accessories</li></ul><p style=\"text-align:justify\">The Supplier shall undertake, at its own expense, the repair or replacement of any defective parts, including the provision of labor, tools, and consumables necessary to restore the goods to their optimal operating condition.</p><p style=\"margin-bottom:0\"><b>3. After-Sales Service Obligations</b></p><p style=\"margin-bottom:0\">The Supplier shall:</p><p style=\"text-align:justify;margin-bottom:0\">a. Maintain or have access to an <b>authorized service center</b> capable of providing adequate technical support within a reasonable distance from the Procuring Entity;<br>b. Ensure the availability of <b>genuine spare parts</b> for a minimum period of <b>five (5) years</b> from delivery;<br>c. Provide <b>preventive maintenance services</b> in accordance with the manufacturer’s recommended schedule, where applicable;<br>d. Respond to service requests within <b>forty-eight (48) to seventy-two (72) hours</b> from receipt of notice;<br>e. Deploy qualified technical personnel to perform necessary inspections, diagnostics, and repairs.</p><p style=\"margin:10px 0 0\"><b>4. Exclusions from Warranty</b></p><p style=\"margin-bottom:2px\">The warranty shall not apply to defects or damages resulting from:</p><ul style=\"margin-top:4px\"><li>Misuse, negligence, or improper operation by the end-user;</li><li>Unauthorized repairs, alterations, or modifications;</li><li>Accidents, force majeure, or external causes beyond normal operating conditions;</li><li>Normal wear and tear of consumable items, unless proven to be factory-defective.</li></ul><p style=\"margin-bottom:0\"><b>5. Warranty Security</b></p><p style=\"text-align:justify\">In accordance with the applicable procurement law and its Implementing Rules and Regulations, the Supplier shall post a <b>warranty security</b> in any of the acceptable forms prescribed by law to guarantee the faithful performance of its warranty obligations.</p><div>{{signatories}}</div>', paper = 'Legal', orientation = 'portrait', layout_json = '{\"margin_top\":18,\"margin_right\":25.4,\"margin_bottom\":18,\"margin_left\":25.4,\"line_height\":1.22,\"cell_pad\":3,\"font_size\":10.5,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":12,\"sig_space\":12,\"lh_space\":4,\"signatories\":[{\"lead\":\"Sincerely yours,\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"CG Omega\"}', required_fields = 'project.title', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'warranty_certificate' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';
UPDATE brgy_templates SET name = 'BAC resolution recommending the award', description = 'Resolution of the Bids and Awards Committee recommending the award to the company (step 13 of the bidding), prepared for the signatures of the BAC and the Punong Barangay.', body = '<div>{{letterhead}}</div><p style=\"text-align:center;margin:0\">Office of the Barangay</p><p style=\"text-align:center;margin:2px 0 2px\"><span style=\"font-size:13pt;font-weight:bold\">BIDS AND AWARDS COMMITTEE</span></p><p style=\"text-align:center;font-weight:bold;margin-bottom:18px\">RESOLUTION NO.__________</p><p style=\"text-align:justify;line-height:1.6\">WHEREAS, after a complete and final evaluation by the BAC Technical Working Group it was determined that <b>{{company.name_upper}}</b> has the CALCULATED RESPONSIVE BID for the {{project.title}} located at <b>{{entity.title_upper}}, {{entity.lgu_line_upper}}</b> for the Contract Price equivalent to <b>{{project.contract_price_text}}</b>.</p><p style=\"text-align:justify;line-height:1.6\">WHEREAS, the Approved Budget for the purchase is in the amount of <b>{{project.abc_text}}</b>.</p><p style=\"text-align:justify;line-height:1.6\">WHEREAS, the Bids and Awards Committee (BAC), through Resolution No.__________ dated______________ had recommended to the Barangay CHAIRMAN, <b>HON. {{entity.head_name_upper}}</b> to award the {{project.title}} located at {{entity.title_upper}}, {{entity.lgu_line_upper}}, to <b>{{company.name_upper}}</b> which recommendation was approved.</p><p style=\"text-align:justify;line-height:1.6\">NOW THEREFORE, we the members of the Bids and Awards Committee (BAC), hereby RESOLVED as it is hereby RESOLVED, to recommend to the Honorable Members, Barangay Council of {{entity.title}}, {{entity.city}}, to authorize <b>HON. {{entity.head_name_upper}}</b>, Barangay CHAIRMAN of {{entity.title_upper}}, {{entity.city}}, to enter into a Contract with <b>{{company.name_upper}}</b> at the Contract Price equivalent to <b>{{project.contract_price_text}}</b>.</p><p style=\"text-align:center;margin-top:14px\">{{entity.title}}, {{entity.city}}</p><div>{{signatories}}</div>', paper = 'Legal', orientation = 'portrait', layout_json = '{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":3,\"sig_top\":8,\"sig_space\":11,\"sig_gap\":6,\"signatories\":[{\"lead\":\"\",\"name\":\"HON. {{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_1_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_2_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_3_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_4_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.bac_member_5_upper}}\",\"pos\":\"BAC Member\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"HON. {{entity.head_name_upper}}\",\"pos\":\"Barangay CHAIRMAN\",\"extra\":\"\",\"align\":\"center\",\"newrow\":1,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"Cambria\"}', required_fields = 'entity.name,project.title', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'bac_resolution' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';
UPDATE brgy_templates SET name = 'Notice of award (NOA)', description = 'Notice of award to the company (step 13 of the bidding), for the Punong Barangay\'s signature and the conforme of the company.', body = '<div>{{letterhead}}</div><p style=\"text-align:center;margin:4px 0 22px\"><span style=\"font-size:14pt;font-weight:bold\">NOTICE OF AWARD</span></p><p>{{date.today}}</p><p style=\"margin-top:18px\"><b>{{signatory.addressee}}</b><br>{{signatory.position_upper}}<br><b>{{company.name_upper}}</b><br>{{company.address}}</p><p style=\"margin-top:18px\">Dear {{signatory.salutation}}:</p><p style=\"text-align:justify;line-height:1.6\">We are happy to notify you that the contract for the <b>{{project.title}}</b> is hereby awarded to you as the single lowest calculated and responsive Bid at a contract price equivalent to <b>{{project.contract_price_text}}</b>.</p><p style=\"text-align:justify;line-height:1.6\">You are therefore required to provide the performance security in the form and amount stipulated in the instruction to the Bidders within ten (10) calendar days from receipt of Notice of Award. Contract signing will be done upon submission of the required performance security. Failure to provide the performance security on the said date shall constitute ground for cancellation of the award and forfeiture of the bid security.</p><div>{{signatories}}</div>', paper = 'Legal', orientation = 'portrait', layout_json = '{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":12,\"sig_space\":10,\"sig_gap\":8,\"signatories\":[{\"lead\":\"Very truly yours,\",\"name\":\"HON. {{entity.head_name_upper}}\",\"pos\":\"Barangay Chairman\",\"extra\":\"{{entity.location}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"Conforme:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{company.name_upper}}\",\"extra\":\"Date: {{date.today}}\",\"align\":\"left\",\"newrow\":1,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"footer\":\"OFFICE OF THE BARANGAY\",\"footer_align\":\"center\",\"footer_bold\":1,\"footer_size\":11,\"footer_pos\":\"bottom\",\"lh_style\":\"barangay\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"Cambria\"}', required_fields = 'entity.name,project.title,project.bid_amount', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'notice_of_award' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';
UPDATE brgy_templates SET name = 'Notice to proceed (NTP)', description = 'Notice to proceed (step 13 of the bidding), for the Punong Barangay\'s signature and the acknowledgment of the company\'s representative.', body = '<div>{{letterhead}}</div><p style=\"text-align:center;margin:4px 0 22px\"><span style=\"font-size:14pt;font-weight:bold\">NOTICE TO PROCEED</span></p><p>{{date.today}}</p><p style=\"margin-top:18px\"><b>{{signatory.addressee}}</b><br>{{signatory.position_upper}}<br><b>{{company.name_upper}}</b><br>{{company.address}}</p><p style=\"margin-top:18px\">Dear {{signatory.salutation}}:</p><p style=\"text-align:justify;text-indent:3em;line-height:1.6\">The attached Purchase Order No. <u>{{po.no}}</u> Dated <u>{{po.date}}</u> having been approved. Notice is hereby given to <b>{{company.name_upper}}</b> on the <b>{{project.title}}</b> and may proceed immediately to the delivery of the items enumerated therein within the specified delivery schedule.</p><p style=\"text-align:justify;line-height:1.6\">Please acknowledge receipt and acceptance of this notice by signing both copies in the space provided below and be guided accordingly.</p><div>{{signatories}}</div><table class=\"fx-plain fx-kv\" style=\"width:100%;margin-top:26px\"><tbody><tr><td class=\"k\" style=\"width:48%\">I acknowledge receipt of this Notice on</td><td>: <u>{{date.today}}</u></td></tr><tr><td class=\"k\">Name of the Representative of the Bidder</td><td>: <u>{{signatory.name}}</u></td></tr><tr><td class=\"k\">Authorized Signature</td><td>: _________________________</td></tr></tbody></table>', paper = 'Legal', orientation = 'portrait', layout_json = '{\"margin_top\":25.4,\"margin_right\":25.4,\"margin_bottom\":25.4,\"margin_left\":25.4,\"line_height\":1.3,\"cell_pad\":3,\"font_size\":11,\"table_size\":10,\"title_size\":14,\"sig_cols\":1,\"sig_top\":12,\"sig_space\":10,\"signatories\":[{\"lead\":\"Sincerely yours,\",\"name\":\"HON. {{entity.head_name_upper}}\",\"pos\":\"Barangay Chairman\",\"extra\":\"{{entity.location}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\",\"paper\":\"Legal\",\"orientation\":\"portrait\",\"date_style\":\"mdy\",\"blank_rows\":0,\"nothing_follows\":0,\"font\":\"Cambria\"}', required_fields = 'entity.name,project.title', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'notice_to_proceed' AND body NOT LIKE '%{{signatories}}%' AND body NOT LIKE '%{{contracts.%';

-- ---------------------------------------------------------------------
--  6. The other templates supplied with the program, when never changed (their text exactly as
--     supplied): {{letterhead}} in place of the fixed header, {{signatories}} in place of the fixed signatures
-- ---------------------------------------------------------------------
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":7,\"margin_right\":7,\"margin_bottom\":7,\"margin_left\":7,\"line_height\":1.25,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":12.5,\"lh_style\":\"none\",\"signatories\":[]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_style\":\"none\",\"signatories\":[]}') ELSE layout_json END WHERE code = 'txn_form';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":3,\"lh_style\":\"none\",\"signatories\":[]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_style\":\"none\",\"signatories\":[]}') ELSE layout_json END WHERE code = 'purchase_request';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9,\"table_size\":9,\"title_size\":13,\"blank_rows\":2,\"lh_style\":\"none\",\"signatories\":[]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_style\":\"none\",\"signatories\":[]}') ELSE layout_json END WHERE code = 'purchase_order';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":3,\"lh_style\":\"none\",\"signatories\":[]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_style\":\"none\",\"signatories\":[]}') ELSE layout_json END WHERE code = 'inspection_acceptance_report';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"blank_rows\":4,\"lh_style\":\"none\",\"signatories\":[]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_style\":\"none\",\"signatories\":[]}') ELSE layout_json END WHERE code = 'requisition_issue_slip';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":8,\"margin_right\":12,\"margin_bottom\":8,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9,\"table_size\":8.5,\"title_size\":13,\"blank_rows\":1,\"lh_space\":3,\"sig_top\":2,\"sig_space\":8,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"half\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_space\":3,\"sig_top\":2,\"sig_space\":8,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"half\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}') ELSE layout_json END, body = '<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:10px 0 6px\">REQUEST FOR QUOTATION</div><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:52%\"></td><td>DATE: {{rfq.date}}<br>Quotation / PR No. {{pr.no}}</td></tr></tbody></table><table class=\"fx-lines\" style=\"width:72%;margin-top:8px\"><tbody><tr><td class=\"lbl-l\">Name of Company:</td><td class=\"val\"></td></tr><tr><td class=\"lbl-l\">Address:</td><td class=\"val\"></td></tr><tr><td class=\"lbl-l\">PhilGEPS No.:</td><td class=\"val\"></td></tr><tr><td class=\"lbl-l\">Project Title:</td><td class=\"val\">{{project.title}}</td></tr><tr><td class=\"lbl-l\">Approved Budget of the Contract:</td><td class=\"val\">PHP {{project.abc_plain}}</td></tr><tr><td class=\"lbl-l\">End-User/ Implementing Office:</td><td><b><u>{{entity.name_upper}}</u></b></td></tr></tbody></table><p style=\"margin-top:12px\"><b>Sir/Madam:</b></p><p>Please quote your lowest price quotation including government taxes on the item/s listed below and submit your quotation duly signed by you or your authorized representative not later than ______________ in an opened envelope.</p><table class=\"fx-plain\" style=\"width:100%\" data-section=\"notes\" title=\"Notes to the supplier\"><tbody><tr><td style=\"width:12%;vertical-align:top\">Note:</td><td>1. All entries must be typewritten<br>2. Delivery period must be within immediate calendar days<br>3. Warranty shall be for a period of three (3) months for supplies, one (1) year for equipment after acceptable by the {{entity.name_upper}} of the delivered goods.<br>4. Price validity shall be for the period of <u>120</u> calendar days.<br>5. Supplier/Contractor shall submit original brochures (if applicable)</td></tr></tbody></table><div>{{signatories}}</div><p style=\"margin:10px 0 2px\">After having carefully read and accepted the General Conditions, I/we submit our quotation/s for the item/s as follows:</p>{{rfq.items}}<table class=\"fx-lines\" style=\"width:100%;margin-top:8px\"><tbody><tr><td class=\"lbl-l\" style=\"width:18%\">Amount in Words:</td><td class=\"val\" colspan=\"3\"></td></tr><tr><td class=\"lbl-l\">Delivery Period:</td><td class=\"val\" style=\"width:32%\">{{rfq.delivery_period}}</td><td class=\"lbl-l\" style=\"width:12%\">Warranty:</td><td class=\"val\"></td></tr><tr><td class=\"lbl-l\">Price Validity:</td><td class=\"val\" colspan=\"3\"></td></tr></tbody></table><table class=\"fx-plain\" style=\"width:100%;margin-top:22px\"><tbody><tr><td style=\"width:58%\"></td><td><div style=\"border-top:1px solid #000;text-align:center\">Signature over Printed Name</div>Contact No:<br>Date:</td></tr></tbody></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'request_for_quotation' AND MD5(body) = '0e70aa07091722622ab2ad9eff07b841';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":10,\"table_size\":9,\"title_size\":13,\"lh_style\":\"none\",\"sig_top\":8,\"signatories\":[{\"lead\":\"Approved by:\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"PUNONG BARANGAY\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_style\":\"none\",\"sig_top\":8,\"signatories\":[{\"lead\":\"Approved by:\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"PUNONG BARANGAY\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:58%\"></td><td>P.R No. : {{pr.no}}<br>Name of Project: {{project.title}}<br>Location of the Project: {{entity.location}}</td></tr></tbody></table><div class=\"fx-title\" style=\"text-align:center;margin:18px 0 4px;text-decoration:underline\">ABSTRACT OF BIDS AS QUOTED</div><p style=\"text-align:right\">( {{abstract.date}} )</p><p><b>Project Name: {{project.title}}<br>Project Location: {{entity.name}}, {{entity.city}}<br>Implementing Office: {{project.end_user}}</b></p><p style=\"margin:12px 0 2px\"><b>Approved Budget for the Contract: {{project.abc}}</b></p>{{abstract.table}}<div style=\"margin-top:34px\">{{entity.bac_signatures}}</div><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'abstract_of_canvass' AND MD5(body) = '27b007a50082f0b784485e2ad072f113';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9,\"table_size\":8.5,\"title_size\":13,\"lh_style\":\"none\",\"signatories\":[]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_style\":\"none\",\"signatories\":[]}') ELSE layout_json END WHERE code = 'disbursement_voucher';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":8,\"signatories\":[{\"lead\":\"Released by:\",\"name\":\"{{transmittal.released_by}}\",\"pos\":\"{{company.name}}\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"Received by:\",\"name\":\"\",\"pos\":\"Signature over Printed Name \\/ Date\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":1,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\"}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"sig_top\":8,\"signatories\":[{\"lead\":\"Released by:\",\"name\":\"{{transmittal.released_by}}\",\"pos\":\"{{company.name}}\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"Received by:\",\"name\":\"\",\"pos\":\"Signature over Printed Name \\/ Date\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":1,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}],\"lh_style\":\"company\"}') ELSE layout_json END, body = '<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 10px\">TRANSMITTAL</div><table class=\"fx-plain\" style=\"width:100%\"><tbody><tr><td style=\"width:60%\">To: <b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</td><td style=\"vertical-align:top\">Transmittal No.: <b>{{transmittal.no}}</b><br>Date: {{transmittal.date}}<br>Transaction: {{project.txn_form_no}}<br>P.O. No.: {{po.no}}</td></tr></tbody></table><p style=\"margin-top:12px\">We are transmitting herewith the following documents for <b>{{project.title}}</b>:</p>{{sop.papers_table}}<p>Kindly acknowledge receipt by signing below and returning a copy of this transmittal.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'document_transmittal' AND MD5(body) = 'd6afb70c87a2ca88afe15d71165064e0';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"signatories\":[],\"lh_style\":\"company\"}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"signatories\":[],\"lh_style\":\"company\"}') ELSE layout_json END, body = '<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:6px 0 10px\">BIDDING FORM</div><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:32%\">Series / project no.</td><td>{{project.no}}   {{project.txn_form_no}}</td></tr><tr><td>Procuring entity</td><td><b>{{entity.name}}</b>, {{entity.city}}, {{entity.province}}</td></tr><tr><td>Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Pre-bid conference</td><td>{{project.prebid}}</td></tr><tr><td>Bid deadline / opening</td><td>{{project.bid_deadline}}</td></tr><tr><td>Requestor / end-user</td><td>{{project.requestor}} {{project.end_user}}</td></tr><tr><td>Inspector</td><td>{{project.inspector}}</td></tr><tr><td>Submission requirements</td><td>{{entity.requirement_notes}}</td></tr><tr><td>Specifications</td><td>{{project.specs}}</td></tr><tr><td>Sales representative</td><td>{{project.sales_rep}}</td></tr></tbody></table>{{lines.table}}', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'bidding_form' AND MD5(body) = '022e42050fd29cd02abe76cd66b19e04';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"half\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"half\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}') ELSE layout_json END, body = '<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:12px 0\">INVITATION TO BID</div><p style=\"text-align:center\"><b>{{project.title}}</b><br>{{project.reference_no}}</p><ol><li>The {{entity.name}}, through its approved budget, intends to apply the sum of <b>{{project.abc_words}} ({{project.abc}})</b> being the Approved Budget for the Contract (ABC) to payments under the contract for {{project.title}}. Bids received in excess of the ABC shall be automatically rejected at bid opening.</li><li>The {{entity.name}} now invites bids for the above procurement project. Delivery of the goods is required within {{project.delivery_days}}. Bidders should have completed a contract similar to the project.</li><li>Bidding will be conducted through open competitive bidding procedures using a non-discretionary \"pass/fail\" criterion as specified in the applicable procurement law and its implementing rules.</li><li>A pre-bid conference shall be held on {{project.prebid}} at {{entity.address}}.</li><li>Bids must be duly received by the BAC Secretariat at {{entity.address}} on or before {{project.bid_deadline}}. Late bids shall not be accepted.</li><li>The {{entity.name}} reserves the right to reject any and all bids, declare a failure of bidding, or not award the contract at any time prior to contract award, without thereby incurring any liability to the affected bidder or bidders.</li></ol><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'invitation_to_bid' AND MD5(body) = 'b468c7a9aee5cf24f7f4f9f474bd4da1';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":6,\"signatories\":[{\"lead\":\"Very truly yours,\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"sig_top\":6,\"signatories\":[{\"lead\":\"Very truly yours,\",\"name\":\"{{entity.bac_chair_upper}}\",\"pos\":\"BAC Chairman\",\"extra\":\"\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}') ELSE layout_json END, body = '<div>{{letterhead}}</div><p style=\"text-align:right\">{{date.today}}</p><p><b>The Audit Team Leader</b><br>Commission on Audit<br>{{entity.city}}, {{entity.province}}</p><p><b>Subject: Invitation to observe the bidding for {{project.title}}</b></p><p>Sir/Madam:</p><p>The Bids and Awards Committee of {{entity.name}} respectfully informs your office of the procurement of <b>{{project.title}}</b> ({{project.reference_no}}) with an Approved Budget for the Contract of {{project.abc}}.</p><p>The pre-bid conference is scheduled on {{project.prebid}} and the opening of bids on {{project.bid_deadline}}, at {{entity.address}}. We would be glad to have a representative of your office attend as observer.</p><p>Thank you.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'letter_to_coa' AND MD5(body) = '18164b19365d3dbe46afc977f044425a';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.treasurer_upper}}\",\"pos\":\"Barangay Treasurer\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"Punong Barangay\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{entity.treasurer_upper}}\",\"pos\":\"Barangay Treasurer\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"Punong Barangay\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}') ELSE layout_json END, body = '<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:12px 0\">APPROVED BUDGET FOR THE CONTRACT</div><table class=\"fx\" style=\"width:100%\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference</td><td>{{project.reference_no}}</td></tr><tr><td>Source of funds</td><td>{{project.funding_source}}</td></tr><tr><td>Approved budget</td><td><b>{{project.abc}}</b> ({{project.abc_words}})</td></tr></tbody></table>{{pr.items}}<p>This is to certify that the above amount is the approved budget for the contract of the project.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'approved_budget_contract' AND MD5(body) = 'd86af12d32ffc7d8d80652eda484649d';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"lh_style\":\"none\",\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"Principal\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"{{project.submitter}}\",\"pos\":\"Attorney-in-fact\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"lh_style\":\"none\",\"sig_top\":12,\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"Principal\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"\",\"name\":\"{{project.submitter}}\",\"pos\":\"Attorney-in-fact\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<div class=\"fx-title\" style=\"text-align:center;margin:6px 0 14px\">SPECIAL POWER OF ATTORNEY</div><p><b>KNOW ALL MEN BY THESE PRESENTS:</b></p><p>I, <b>{{signatory.name}}</b>, of legal age, Filipino, {{signatory.position}} of <b>{{company.name}}</b>, with business address at {{company.address}}, do hereby name, constitute and appoint <b>{{project.submitter}}</b>, of legal age, as my true and lawful attorney-in-fact, for me and in my name, place and stead, to do and perform the following acts:</p><ol><li>To attend the pre-bid conference and the opening of bids of <b>{{project.title}}</b> ({{project.reference_no}}) of the {{entity.name}};</li><li>To submit, sign and receive all documents relative to the said bidding, including the bid, clarifications and notices;</li><li>To do all acts necessary and incidental to the foregoing.</li></ol><p>HEREBY GIVING AND GRANTING unto my said attorney-in-fact full power and authority to do and perform the acts above, and hereby ratifying all that my said attorney-in-fact shall lawfully do by virtue hereof.</p><p>IN WITNESS WHEREOF, I have hereunto set my hand this ____ day of __________ at __________.</p><div>{{signatories}}</div><p style=\"margin-top:22px\"><b>ACKNOWLEDGMENT</b></p><p>[Notarial acknowledgment]</p>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'special_power_of_attorney' AND MD5(body) = '2d151f0da50746dff83138d7b7b8380c';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"margin_top\":10,\"margin_right\":12,\"margin_bottom\":10,\"margin_left\":12,\"line_height\":1.2,\"cell_pad\":2,\"font_size\":9.5,\"table_size\":9,\"title_size\":13,\"sig_top\":14,\"signatories\":[{\"lead\":\"Inspected by:\",\"name\":\"{{project.inspector_upper}}\",\"pos\":\"Inspector\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"Approved by:\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"Barangay Captain\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"sig_top\":14,\"signatories\":[{\"lead\":\"Inspected by:\",\"name\":\"{{project.inspector_upper}}\",\"pos\":\"Inspector\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0},{\"lead\":\"Approved by:\",\"name\":\"{{entity.head_name_upper}}\",\"pos\":\"Barangay Captain\",\"extra\":\"\",\"align\":\"center\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":1,\"upper\":0,\"italic\":0}],\"lh_style\":\"barangay\"}') ELSE layout_json END, body = '<div>{{letterhead}}</div><div class=\"fx-title\" style=\"text-align:center;margin:16px 0\">CERTIFICATE OF COMPLETION</div><p>This is to certify that <b>{{company.name}}</b> has satisfactorily completed / delivered <b>{{project.title}}</b> under {{project.contract_ref}} for the <b>{{entity.name}}</b> in accordance with the specifications, in the amount of <b>{{project.contract_amount}}</b>.</p><p>Date of completion: <b>{{project.completion_date}}</b></p><p>Issued this ____ day of __________ for whatever legal purpose it may serve.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'certificate_of_completion' AND MD5(body) = 'b38b7d9afe11a185b16ba4d06d367b9c';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Subject: Submission of bid / quotation for {{project.title}} ({{project.reference_no}})</b></p><p>Dear Sir / Madam:</p><p>In response to your invitation, {{company.name}} respectfully submits its bid / quotation for <b>{{project.title}}</b> in the total amount of <b>{{project.bid_amount}}</b> ({{project.bid_amount_words}}), inclusive of all applicable taxes, under the terms and specifications of your request.</p><p>Enclosed are the documents your request asks for, as listed in our checklist:</p>{{requirements.table}}<p>Our offer is valid for the period stated in your bidding documents. For clarifications, please contact the undersigned at {{company.phone}} or {{company.email}}.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'cover_letter' AND MD5(body) = '083e1f3d048f8c39ec262a86b67f0847';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><h2 style=\"text-align:center;margin:10px 0 14px\">COMPANY PROFILE</h2><table class=\"ft\"><tbody><tr><td style=\"width:34%\">Registered name</td><td><b>{{company.name}}</b></td></tr><tr><td>Business address</td><td>{{company.address}}</td></tr><tr><td>Registration</td><td>{{company.reg_no}}</td></tr><tr><td>TIN / tax status</td><td>{{company.tin}}   ({{company.vat_status}})</td></tr><tr><td>PhilGEPS registration</td><td>{{company.philgeps_no}}   {{company.philgeps_class}}</td></tr><tr><td>Contact</td><td>{{company.phone}}   {{company.email}}</td></tr><tr><td>Authorized representative</td><td>{{signatory.name}}, {{signatory.position}}</td></tr></tbody></table><h3>Lines of business</h3><p>Supply and delivery of office, school, medical and household supplies, IT equipment and furniture; general services (janitorial, maintenance, repairs); and, through its licensed construction arm, minor infrastructure works for barangays and local government units.</p><h3>Facilities and people</h3><p>[Describe the warehouse, delivery vehicles, technical staff and the after-sales service offered.]</p><h3>Major government clients</h3><p>[List recent contracts: entity, project, amount, date completed.]</p>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'company_profile' AND MD5(body) = '84ff4248ca1d220e3c589771f5702ed3';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"signatories\":[{\"lead\":\"Submitted by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"signatories\":[{\"lead\":\"Submitted by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PRICE QUOTATION</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>We offer to supply the following under the terms of your request for quotation:</p>{{lines.table}}<p><b>Total amount: {{lines.total}}</b> ({{lines.total_words}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Delivery period</td><td>{{project.delivery_days}} from receipt of the purchase order / notice to proceed</td></tr><tr><td>Delivery site</td><td>{{project.delivery_site}}</td></tr><tr><td>Warranty</td><td>{{project.warranty_months}}</td></tr><tr><td>Payment terms</td><td>{{project.payment_terms}}</td></tr><tr><td>Validity of the offer</td><td>As stated in the RFQ</td></tr></tbody></table><p>Prices include all applicable taxes, delivery and handling. We confirm that the items offered comply with the specifications stated in your request.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'quotation' AND MD5(body) = '72d606b5d4b92a5bed26e33ae17e3703';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"signatories\":[{\"lead\":\"\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PRICE SCHEDULE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p></p>{{lines.table}}<p><b>Total bid price: {{lines.total}}</b><br>({{lines.total_words}})</p><p>Name of bidder: <b>{{company.name}}</b><br>Signature of the authorized representative:</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'price_schedule' AND MD5(body) = '9b6d58c0dd06b69668d62fdbd96ee752';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"signatories\":[{\"lead\":\"Certified correct:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"signatories\":[{\"lead\":\"Certified correct:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">TECHNICAL PROPOSAL AND STATEMENT OF COMPLIANCE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>We state below, item by item, our compliance with the technical specifications. Where \"Comply\" is stated, the offer meets or exceeds the requirement; supporting brochures and data sheets are attached.</p><table class=\"ft\"><thead><tr><th style=\"width:6%\">Item</th><th>Specification required</th><th style=\"width:30%\">Offer (brand, model, specification)</th><th style=\"width:12%\">Statement</th></tr></thead><tbody><tr><td>1</td><td>{{project.specs}}</td><td>[Brand / model offered]</td><td>Comply</td></tr></tbody></table><p><b>Delivery:</b> {{project.delivery_days}} at {{project.delivery_site}}. <b>Warranty:</b> {{project.warranty_months}}.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'technical_proposal' AND MD5(body) = 'eadb6d262ca10cccc1486ee6138f118b';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"signatories\":[{\"lead\":\"Prepared by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"signatories\":[{\"lead\":\"Prepared by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">METHOD STATEMENT</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><h3>1. Scope</h3><p>{{project.specs}}</p><h3>2. Mobilization</h3><p>[Site set-up, permits, coordination with the barangay and the end-user ({{project.end_user}}).]</p><h3>3. Sequence of work</h3><ol><li>[Activity]</li><li>[Activity]</li><li>[Activity]</li></ol><h3>4. Manpower and equipment</h3><p>[List of key personnel and equipment.]</p><h3>5. Quality control and testing</h3><p>[Tests, inspections and hold points; acceptance by the entity\'s inspection committee.]</p><h3>6. Safety and environment</h3><p>[Safety plan, signage, housekeeping, disposal.]</p><h3>7. Schedule</h3><p>Completion within {{project.delivery_days}} from the notice to proceed.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'method_statement' AND MD5(body) = '67d45c4b0dd3c89191736e8bb0e1601a';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"signatories\":[{\"lead\":\"Prepared by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"signatories\":[{\"lead\":\"Prepared by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">IMPLEMENTATION / DELIVERY SCHEDULE</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><table class=\"ft\"><thead><tr><th style=\"width:6%\">No.</th><th>Activity / delivery</th><th style=\"width:18%\">Start</th><th style=\"width:18%\">Finish</th><th style=\"width:16%\">Weight %</th></tr></thead><tbody><tr><td>1</td><td>Mobilization / receipt of PO or NTP</td><td>Day 1</td><td>Day 3</td><td>5</td></tr><tr><td>2</td><td>[Delivery / work package]</td><td></td><td></td><td></td></tr><tr><td>3</td><td>Inspection and acceptance</td><td></td><td></td><td></td></tr></tbody></table><p>Total contract period: {{project.delivery_days}}.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'implementation_schedule' AND MD5(body) = '47df1d8d28447dbe582f2357c68ba7ce';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">SUPPLY AND SERVICES PROPOSAL</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>{{company.name}} proposes to supply and deliver the items below, together with the related services described, for <b>{{lines.total}}</b>.</p>{{lines.table}}<h3>Related services</h3><ul><li>Delivery, unloading and installation at {{project.delivery_site}}</li><li>Orientation of the end-users</li><li>Warranty service: {{project.warranty_months}}</li></ul><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'supply_proposal' AND MD5(body) = 'f3184b695b3ed1ab1099d42c9bccd5b0';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">SCOPE-OF-WORK PROPOSAL</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><h3>Scope of work</h3><p>{{project.specs}}</p><h3>Deliverables</h3><ul><li>[Deliverable]</li><li>[Deliverable]</li></ul><h3>Exclusions</h3><p>[Items not included.]</p><h3>Price</h3>{{lines.table}}<p>Duration: {{project.delivery_days}}. Payment: {{project.payment_terms}}.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'scope_of_work' AND MD5(body) = '880aa2a1bf0266f29355d4489da5ad0d';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"signatories\":[{\"lead\":\"Requested by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"signatories\":[{\"lead\":\"Requested by:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">REQUEST FOR QUOTATION (SUPPLIER / SUBCONTRACTOR)</h2><p>To: [Supplier / subcontractor]<br>Address: [Address]</p><p>We are preparing an offer for <b>{{project.title}}</b> for {{entity.name}}. Please quote your best price and delivery for the following, valid for at least 30 days:</p>{{lines.table}}<p>Please include with your quotation: your business permit, BIR registration, product certifications or licenses, warranty terms and delivery lead time. Prices to us are separate from our prices to the procuring entity; this request does not disclose the entity\'s budget.</p><p>Reply to {{project.preparer}} at {{company.email}} by [date].</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'supplier_request' AND MD5(body) = 'aa05ef4596a5f0f26120a8b88614f66e';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">INTERNAL BID APPROVAL SHEET</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project no.</td><td>{{project.no}}</td></tr><tr><td>Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode / law</td><td>{{project.mode}}, {{project.regime}}</td></tr><tr><td>ABC</td><td>{{project.abc}}</td></tr><tr><td>Bid amount</td><td><b>{{project.bid_amount}}</b></td></tr><tr><td>Bid deadline</td><td>{{project.bid_deadline}}</td></tr></tbody></table><h3>Costing and margin (confidential)</h3>{{costing.table}}<h3>Compliance checklist</h3>{{requirements.table}}<h3>Remarks</h3><p>[Risks, assumptions, supplier quotations relied on, payment record of the entity.]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.preparer}}</div><div>Prepared by</div></td><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.checker}}</div><div>Checked by</div></td><td style=\"width:33%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.approver}}</div><div>Approved by</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'bid_approval_sheet' AND MD5(body) = '2444095691f7876adb6dc209fcc479a4';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">CONTRACT REVIEW SHEET</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b> ({{project.no}})</td></tr><tr><td>Notice of award</td><td>{{project.noa_ref}}, {{project.noa_date}}</td></tr><tr><td>Contract / PO no.</td><td>{{project.contract_ref}}</td></tr><tr><td>Amount awarded</td><td>{{project.contract_amount}}</td></tr><tr><td>Delivery / completion</td><td>{{project.delivery_days}}; due {{project.due_date}}</td></tr><tr><td>Retention</td><td>{{project.retention_pct}}</td></tr><tr><td>Liquidated damages</td><td>{{project.ld_rate}}</td></tr><tr><td>Warranty</td><td>{{project.warranty_months}}</td></tr><tr><td>Payment terms</td><td>{{project.payment_terms}}</td></tr></tbody></table><h3>Checks</h3><table class=\"ft\"><thead><tr><th>Point</th><th style=\"width:16%\">OK</th><th style=\"width:36%\">Remarks</th></tr></thead><tbody><tr><td>Items, quantities and prices agree with the approved bid</td><td></td><td></td></tr><tr><td>Delivery period and site can be met</td><td></td><td></td></tr><tr><td>Performance security / warranty requirements understood</td><td></td><td></td></tr><tr><td>Billing documents and payment terms understood</td><td></td><td></td></tr><tr><td>Taxes to be withheld by the entity noted</td><td></td><td></td></tr></tbody></table><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.checker}}</div><div>Reviewed by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.approver}}</div><div>Approved by</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'contract_review_sheet' AND MD5(body) = '18395bfd0240256c259764540fbacc39';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PROJECT HANDOVER MEMO</h2><p><b>To:</b> {{project.pm}}, Project Manager; Warehouse and Delivery<br><b>From:</b> {{project.preparer}}<br><b>Re:</b> {{project.title}} ({{project.no}})</p><p>The contract below was awarded to the company by {{entity.name}} (notice of award {{project.noa_ref}}, {{project.noa_date}}). Please mobilize as follows:</p>{{lines.contract_table}}<table class=\"ft\"><tbody><tr><td style=\"width:32%\">Delivery site</td><td>{{project.delivery_site}}</td></tr><tr><td>Due</td><td>{{project.due_date}}</td></tr><tr><td>End-user</td><td>{{project.end_user}}</td></tr><tr><td>Warranty</td><td>{{project.warranty_months}}</td></tr></tbody></table><p>Deliveries are recorded on Deliveries &amp; Acceptance; the signed delivery receipt and the inspection and acceptance report are filed in the Document Vault, as billing depends on them.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.preparer}}</div><div>Handed over by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.pm}}</div><div>Received by</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'handover_memo' AND MD5(body) = '0aac4c78890328ab89a7e71c09f9df5c';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><h2 style=\"text-align:center;margin:10px 0 14px\">DELIVERY RECEIPT</h2><table class=\"ft\"><tbody><tr><td style=\"width:24%\">DR no.</td><td><b>{{delivery.no}}</b></td><td style=\"width:20%\">Date</td><td>{{delivery.date}}</td></tr><tr><td>Delivered to</td><td colspan=\"3\">{{entity.name}}, {{delivery.to}}</td></tr><tr><td>Project</td><td colspan=\"3\">{{project.title}} (contract / PO {{project.contract_ref}})</td></tr></tbody></table><p></p>{{delivery.table}}<p>Received the above items in good order and condition, subject to inspection and acceptance by the entity.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Delivered by ({{company.name}})</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{delivery.received_by}} {{delivery.received_position}}</div><div>Received by (name, position, date)</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'delivery_receipt' AND MD5(body) = '127a443121fd8e5393595fe3cdeec661';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">SERVICE / ACCOMPLISHMENT REPORT</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b></td></tr><tr><td>Reference (PR / RFQ / ITB)</td><td>{{project.reference_no}}</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Mode of procurement</td><td>{{project.mode}}</td></tr><tr><td>Approved budget (ABC)</td><td>{{project.abc}}</td></tr></tbody></table><p>Period covered: [from] to [to]</p>{{delivery.table}}<h3>Work done</h3><p>[Describe the services rendered / work accomplished, with dates.]</p><h3>Issues and actions</h3><p>[None]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.pm}}</div><div>Submitted by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{entity.end_user}}</div><div>Certified by the end-user</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'accomplishment_report' AND MD5(body) = '08b6a8279c28acb6c85c6cbd83bd7cc7';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">TRANSMITTAL</h2><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Re: {{project.title}}</b></p><p>We transmit the following documents for your appropriate action:</p><table class=\"ft\"><thead><tr><th style=\"width:6%\">No.</th><th>Document</th><th style=\"width:16%\">Copies</th></tr></thead><tbody><tr><td>1</td><td>[Document]</td><td>1</td></tr><tr><td>2</td><td>[Document]</td><td>1</td></tr></tbody></table><p>Kindly acknowledge receipt by signing below.</p><div>{{signatories}}</div><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Received by (name, position)</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Date and time received</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'transmittal' AND MD5(body) = '6617a4d02ba534779d9822df9a46e784';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Subject: Request for payment, {{billing.type}} {{billing.no}} for {{project.title}}</b></p><p>Dear Sir / Madam:</p><p>We respectfully request payment of <b>{{billing.gross}}</b> ({{billing.gross_words}}) for the deliveries / services accepted under {{project.contract_ref}}, as detailed below:</p>{{billing.table}}<p>Enclosed are our sales invoice no. {{billing.si_no}}, the statement of account, and the signed delivery and inspection and acceptance documents.</p><p>Payment may be made by check payable to <b>{{company.name}}</b> or by credit to: {{company.bank_details}}. Kindly furnish us BIR Form 2307 for the taxes withheld.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'billing_cover_letter' AND MD5(body) = 'b4f0fc93b8572b4764db5b8fb2f91518';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">STATEMENT OF ACCOUNT</h2><table class=\"ft\"><tbody><tr><td style=\"width:24%\">Bill to</td><td><b>{{entity.name}}</b><br>{{entity.address}}</td></tr><tr><td>Project</td><td>{{project.title}} ({{project.no}})</td></tr><tr><td>Contract / PO</td><td>{{project.contract_ref}}, {{project.contract_amount}}</td></tr></tbody></table><p></p>{{soa.table}}<p>Please make payment to {{company.name}}: {{company.bank_details}}.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Prepared by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{signatory.name}}</div><div>Noted by</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'statement_of_account' AND MD5(body) = 'e5016e5358333b173308e55d501bfe76';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.treasurer}}</b><br>Treasurer<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Subject: Follow-up of payment, {{project.title}}</b></p><p>Dear Sir / Madam:</p><p>May we respectfully follow up the payment of our billing for the above project, which has been accepted and is now due. Our records show the following:</p>{{soa.table}}<p>Should any document be lacking for the processing of the payment, please let us know so we can provide it at once.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'collection_followup' AND MD5(body) = '8b09a9bbbc1ed4c3edd50057f2a5ad01';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><h2 style=\"text-align:center;margin:10px 0 14px\">ACKNOWLEDGMENT RECEIPT</h2><table class=\"ft\"><tbody><tr><td style=\"width:26%\">No.</td><td>{{collection.no}}</td><td style=\"width:16%\">Date</td><td>{{collection.date}}</td></tr></tbody></table><p>Received from <b>{{entity.name}}</b> the amount of <b>{{collection.amount_words}} ({{collection.amount}})</b> by {{collection.reference}}, in payment of billing {{billing.no}} (sales invoice no. {{billing.si_no}}) for {{project.title}}.</p>{{collection.table}}<p style=\"margin-top:14px;font-weight:bold;text-align:center;border:1px solid #000;padding:6px\">THIS DOCUMENT IS NOT VALID FOR CLAIM OF INPUT TAX.</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:100%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Received by (cashier / collector)</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'acknowledgment_receipt' AND MD5(body) = '31f394422c5d32276540ff8b707295ad';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">CONTRACT RECONCILIATION SHEET</h2><p><b>{{project.title}}</b> ({{project.no}}), {{entity.name}}</p>{{closeout.table}}<h3>Statement of account</h3>{{soa.table}}<h3>Differences and actions</h3><p>[None]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Prepared by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\"> </div><div>Checked by (accounting)</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'reconciliation_sheet' AND MD5(body) = 'f488dd37c278c265634b63a877702c15';
UPDATE brgy_templates SET body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><h2 style=\"text-align:center;margin:10px 0 14px\">PROJECT COMPLETION AND CLOSEOUT SUMMARY</h2><table class=\"ft\"><tbody><tr><td style=\"width:32%\">Project</td><td><b>{{project.title}}</b> ({{project.no}})</td></tr><tr><td>Procuring entity</td><td>{{entity.name}}</td></tr><tr><td>Contract</td><td>{{project.contract_ref}}, NOA {{project.noa_ref}}</td></tr><tr><td>Warranty until</td><td>{{project.warranty_until}}</td></tr></tbody></table><h3>Final figures</h3>{{closeout.table}}<h3>Papers on file</h3>{{requirements.all_table}}<h3>Lessons learned</h3><p>[What went well, what to change next time.]</p><table class=\"sig-table\" style=\"width:100%;border-collapse:collapse;margin-top:26px\"><tr><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.pm}}</div><div>Prepared by</div></td><td style=\"width:50%;vertical-align:top;padding:28px 10px 0 0\"><div style=\"border-bottom:1px solid #000;min-height:22px\">{{project.approver}}</div><div>Approved by</div></td></tr></table>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'closeout_summary' AND MD5(body) = 'bfaf7f6218991a1fe8499cb0d110968d';
UPDATE brgy_templates SET layout_json = CASE WHEN layout_json IS NULL OR layout_json IN ('', '{}', '[]', 'null') THEN '{\"signatories\":[{\"lead\":\"Conforme:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}' WHEN layout_json LIKE '{%}' AND layout_json NOT LIKE '%"lh\_style"%' AND layout_json NOT LIKE '%"signatories"%' THEN CONCAT(LEFT(layout_json, CHAR_LENGTH(layout_json) - 1), ',\"signatories\":[{\"lead\":\"Conforme:\",\"name\":\"{{signatory.name}}\",\"pos\":\"{{signatory.position}}\",\"extra\":\"{{company.name}}\",\"align\":\"left\",\"newrow\":0,\"line\":0,\"bold\":1,\"underline\":0,\"upper\":0,\"italic\":0}]}') ELSE layout_json END, body = '<div>{{letterhead}}</div><p style=\"text-align:right;margin:0 0 6px\">{{doc.no}}<br>{{date.today}}</p><p><b>{{entity.head_name}}</b><br>{{entity.head_position}}<br>{{entity.name}}<br>{{entity.address}}</p><p><b>Attention:</b> The Chairperson, Bids and Awards Committee  ({{entity.bac_chair}})</p><p><b>Subject: Acceptance of Purchase Order / Notice of Award, {{project.title}}</b></p><p>Dear Sir / Madam:</p><p>We acknowledge receipt of your Notice of Award {{project.noa_ref}} dated {{project.noa_date}} and Purchase Order {{project.po_no}} for <b>{{project.contract_amount}}</b>, and confirm our acceptance (conforme) of their terms.</p><p>We will deliver to {{project.delivery_site}} within {{project.delivery_days}}, on or before {{project.due_date}}. Our contact person for this contract is {{project.pm}}.</p><div>{{signatories}}</div>', version_no = version_no + 1, updated_at = NOW()
 WHERE code = 'po_conforme' AND MD5(body) = '5d50ec6073021adb0ae8a23e68ec7aeb';

-- the version of each template changed above (the version before stays)
INSERT INTO brgy_template_versions (template_id, version_no, name, body, layout_json, positions_json, change_note)
SELECT t.id, t.version_no, t.name, t.body, t.layout_json, t.positions_json,
       CASE WHEN t.code IN ('supplier_profile','technical_specifications','notice_of_post_qualification') THEN 'Supplied with the program' WHEN t.code IN ('statement_ongoing_contracts','statement_similar_contracts','letter_of_intent','production_details','manpower_schedule','warranty_certificate','bac_resolution','notice_of_award','notice_to_proceed') THEN 'Redesigned from the company''s form (steps 8 and 13 of the bidding)' ELSE 'Letterhead and signatories set on the Format tab' END
  FROM brgy_templates t
 WHERE t.code IN ('supplier_profile','technical_specifications','notice_of_post_qualification','statement_ongoing_contracts','statement_similar_contracts','letter_of_intent','production_details','manpower_schedule','warranty_certificate','bac_resolution','notice_of_award','notice_to_proceed','request_for_quotation','abstract_of_canvass','document_transmittal','bidding_form','invitation_to_bid','letter_to_coa','approved_budget_contract','special_power_of_attorney','certificate_of_completion','cover_letter','company_profile','quotation','price_schedule','technical_proposal','method_statement','implementation_schedule','supply_proposal','scope_of_work','supplier_request','bid_approval_sheet','contract_review_sheet','handover_memo','delivery_receipt','accomplishment_report','transmittal','billing_cover_letter','statement_of_account','collection_followup','acknowledgment_receipt','reconciliation_sheet','closeout_summary','po_conforme')
   AND NOT EXISTS (SELECT 1 FROM brgy_template_versions v WHERE v.template_id = t.id AND v.version_no = t.version_no);

-- ---------------------------------------------------------------------
--  7. The pre-printed transaction form: the X marks of Cash Out and Kaliwaan (above Purchases)
-- ---------------------------------------------------------------------
UPDATE brgy_templates SET positions_json = REPLACE(positions_json, '{"key":"txn.mark_purchases"', '{\"key\":\"txn.mark_cash_out\",\"text\":\"\",\"x\":45.5,\"y\":35,\"w\":5,\"size\":10,\"bold\":1,\"align\":\"center\",\"upper\":0},{\"key\":\"txn.mark_kaliwaan\",\"text\":\"\",\"x\":45.5,\"y\":42,\"w\":5,\"size\":10,\"bold\":1,\"align\":\"center\",\"upper\":0},{\"key\":\"txn.mark_purchases\"')
 WHERE code = 'txn_form' AND positions_json LIKE '%{"key":"txn.mark\_purchases"%' AND positions_json NOT LIKE '%txn.mark\_cash\_out%';

-- ---------------------------------------------------------------------
--  8. Record the change in the audit trail
-- ---------------------------------------------------------------------
INSERT INTO audit_trail (username, user_roles, ip_address, workstation, module, page_key, action, record_type, record_ref, reason)
VALUES ('system', 'Database migration', '127.0.0.1', 'SQL migration', 'brgy', 'brgy.templates', 'edit', 'template',
        'Letterheads, signatories, bid forms of steps 8 and 13, Cash Out and Kaliwaan',
        'Migration 2026_11_10: letterheads, logos and signatories on the Format tab; the forms of steps 8 and 13 redesigned; transaction types Cash Out and Kaliwaan');

